package com.renthub.auth; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") @CrossOrigin(origins="http://localhost:5173") public class AuthController {private final AuthService auth; public AuthController(AuthService a){auth=a;} public record RegisterRequest(@NotBlank String fullName,@Email @NotBlank String email,@Size(min=6) String password){} public record LoginRequest(@Email @NotBlank String email,@NotBlank String password){} @PostMapping("/register") public AuthService.AuthResponse register(@Valid @RequestBody RegisterRequest r){return auth.register(r.fullName(),r.email(),r.password());} @PostMapping("/login") public AuthService.AuthResponse login(@Valid @RequestBody LoginRequest r){return auth.login(r.email(),r.password());} @GetMapping("/me") public AuthService.UserView me(@RequestHeader(value="Authorization",required=false) String h){return auth.me(h);} @PostMapping("/logout") public void logout(@RequestHeader(value="Authorization",required=false) String h){auth.logout(h);} }
